// -----------------------------------------------------------------------------
// Journey Booking — Capture Payment Request DTO
// -----------------------------------------------------------------------------

import { ApiProperty } from '@nestjs/swagger';

import { IsString, MaxLength, MinLength } from 'class-validator';

// -----------------------------------------------------------------------------

/**
 * Request payload for capturing an authorized Journey Booking payment.
 *
 * The booking public ID is supplied through the route parameter.
 * The correlation ID is generated by the controller.
 * No additional request body fields are required for this operation.
 *
 * This DTO intentionally has no client-supplied technical identifiers.
 */
export class CaptureJourneyBookingPaymentDto {
  @ApiProperty({
    description:
      'No request body fields are required for payment capture. This DTO is retained only if the HTTP endpoint is configured to validate an explicit body.',
    required: false,
  })
  @IsString()
  @MinLength(1)
  @MaxLength(100)
  _placeholder!: string;
}

// -----------------------------------------------------------------------------
// Default Export
// -----------------------------------------------------------------------------

export default CaptureJourneyBookingPaymentDto;
